-- Social Media Creators: Marketing category and channel-focused job profile.
ALTER TABLE public.talent_users DROP CONSTRAINT IF EXISTS talent_users_signup_form_type_check;
ALTER TABLE talent_users ADD CONSTRAINT talent_users_signup_form_type_check CHECK (signup_form_type IS NULL OR signup_form_type IN ('creative','accountant','sales','creative_director','copy_content_writer','social_media_manager','videographer','photographer','videographer_photographer','ai_video_image_creator','ads_specialist','seo_specialist','digital_marketing_team','influencer_marketing','offline_marketing','web_development','app_building','automation','software_solutions','cfo_ca','gst_experts','tds_experts','labour_law','incorporation','contract_drafting','ip_protection','compliance','business_formation','end_to_end_hiring','team_building','hr_process','social_media_creator'));
-- Preserve actual course completion; this flag exempts creator accounts from training.
UPDATE public.talent_users SET skip_onboarding=TRUE WHERE signup_form_type='social_media_creator' OR signup_categories @> ARRAY['social-media-creator']::text[];
